import{_ as a,o as t,c as n,a5 as r}from"./chunks/framework.CsGesDJn.js";const h=JSON.parse('{"title":"Content Humanizer","description":"","frontmatter":{},"headers":[],"relativePath":"feature/content-humanizer/spec.md","filePath":"feature/content-humanizer/spec.md"}'),i={name:"feature/content-humanizer/spec.md"};function o(s,e,d,c,l,u){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="content-humanizer" tabindex="-1">Content Humanizer <a class="header-anchor" href="#content-humanizer" aria-label="Permalink to &quot;Content Humanizer&quot;">​</a></h1><h2 id="objective" tabindex="-1">Objective <a class="header-anchor" href="#objective" aria-label="Permalink to &quot;Objective&quot;">​</a></h2><p>Apply blader/humanizer to BrandHub&#39;s AI content so captions read naturally in Vietnamese and English while keeping the creator&#39;s message and verified product facts.</p><h2 id="user-story" tabindex="-1">User story <a class="header-anchor" href="#user-story" aria-label="Permalink to &quot;User story&quot;">​</a></h2><p>As a creator, I generate or revise content through the existing forms and receive publishable copy without chatbot introductions, empty hype, or an editing report.</p><h2 id="acceptance-criteria" tabindex="-1">Acceptance criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance criteria&quot;">​</a></h2><ul><li>Install the upstream skill for Codex and retain its pinned source and MIT notice in the AI service.</li><li>Use a compact adaptation in caption generation, refinement, platform adaptation, and both topic and prompt modes of the content endpoint.</li><li>Draft and review within the existing model request. Do not introduce another provider request, endpoint, dependency, credit operation, or UI control.</li><li>Preserve verified names, numbers, offers, dates, URLs, quotations, intent, requested language, brand voice, platform limits, CTA, and hashtag requirements. Writing samples guide style, not factual claims.</li><li>Keep deliberate humor, slang, hooks, and approved brand expression. Never invent personal experience or endorsements to sound human.</li><li>Return only the existing text or JSON contract, without drafts, critique, or Humanizer instructions.</li><li>Existing provider routing, fact checks, moderation, and failure handling still run.</li></ul><h2 id="ui-ux-and-api-contract" tabindex="-1">UI/UX and API contract <a class="header-anchor" href="#ui-ux-and-api-contract" aria-label="Permalink to &quot;UI/UX and API contract&quot;">​</a></h2><p>Existing forms, routes, request models, and response models stay in use. No new displayed text, locale keys, or theme styles are needed; VI/EN and light/dark UI behavior are unaffected.</p><h2 id="error-handling-and-edge-cases" tabindex="-1">Error handling and edge cases <a class="header-anchor" href="#error-handling-and-edge-cases" aria-label="Permalink to &quot;Error handling and edge cases&quot;">​</a></h2><p>Existing provider errors and malformed JSON rejection apply. Humanizer is prompt guidance, not a deterministic guarantee of writing quality or factual accuracy. Missing facts must be omitted, not invented; a marketing CTA must not be mistaken for chatbot residue.</p><h2 id="definition-of-done" tabindex="-1">Definition of done <a class="header-anchor" href="#definition-of-done" aria-label="Permalink to &quot;Definition of done&quot;">​</a></h2><p>Focused mocked tests verify one generation call per operation, Humanizer guidance on each path, and preserved response/fact-check behavior. No paid provider call is needed for implementation verification.</p><h2 id="out-of-scope" tabindex="-1">Out of scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of scope&quot;">​</a></h2><p>Video worker integration, changes to trend analysis or image prompts, AI-detector evasion, model training, and unrelated pending repository changes.</p>',15)])])}const m=a(i,[["render",o]]);export{h as __pageData,m as default};
